def resolve(path, cwd, links):
    """
    Resolve a path to its canonical absolute form, following symlinks.

    Args:
        path: A path string (absolute if starts with '/', else relative to cwd)
        cwd: Current working directory (canonical absolute path)
        links: Dict mapping canonical absolute paths to symlink targets

    Returns:
        Canonical absolute path, or None on error
    """

    # Start with absolute path
    if path.startswith('/'):
        current = '/'
        remaining = path[1:]
    else:
        current = cwd
        remaining = path

    link_count = 0
    max_links = 8

    while True:
        # Split remaining path into components
        components = remaining.split('/')

        # Process each component
        for component in components:
            # Skip empty components and '.'
            if component == '' or component == '.':
                continue

            # Handle '..'
            if component == '..':
                if current != '/':
                    current = current.rsplit('/', 1)[0]
                    if current == '':
                        current = '/'
                continue

            # Append the component to current path
            if current == '/':
                candidate = '/' + component
            else:
                candidate = current + '/' + component

            # Check if this is a symlink
            if candidate in links:
                link_count += 1
                if link_count > max_links:
                    return None

                # Get the symlink target
                target = links[candidate]

                # Determine the remaining components after this one
                idx = components.index(component)
                remaining_after = '/'.join(components[idx + 1:])

                # Resolve the target
                if target.startswith('/'):
                    current = '/'
                    target_path = target[1:]
                else:
                    # Target is relative to the directory containing the link
                    if candidate == '/':
                        current = '/'
                    else:
                        current = candidate.rsplit('/', 1)[0]
                        if current == '':
                            current = '/'
                    target_path = target

                # Combine target with remaining components
                if remaining_after:
                    remaining = target_path + '/' + remaining_after if target_path else remaining_after
                else:
                    remaining = target_path

                # Break inner loop to restart with new remaining path
                break
            else:
                # Not a symlink, just update current
                current = candidate
        else:
            # No symlink was followed, we're done
            break

    # Return result without trailing slash (except for root)
    if current == '/':
        return '/'
    else:
        return current

